    "analysis": "【审题】关键词：3 的 1/(x−1) 次方、根号 4−x²、求定义域。这是「多个基本初等函数复合后求定义域」的题，必须让每个部分都有意义。两处限制：分式的分母不能为 0、偶次根号内必须非负。\n\n【思路】逐一列出所有限制条件再取交集：① 指数 1/(x−1) 要求 x−1≠0；② 根号 √(4−x²) 要求 4−x²≥0。解出两个范围后取交集，注意端点 1 要排除、−2 和 2 可以取到。\n\n【步骤】\n① 由 1/(x−1) 有意义得 x−1≠0，即 x≠1。\n② 由 √(4−x²) 有意义得 4−x²≥0，即 x²≤4，解得 −2≤x≤2。\n③ 取交集：在 [−2,2] 中去掉 x=1，得 [−2,1)∪(1,2]。\n\n【答案】定义域为 [−2,1)∪(1,2]，对应选项 B。\n\n【易错】1. 误选 A：漏掉 x−1≠0，没排除 x=1。2. 误选 C：只看了指数部分附近，范围算错。3. 误选 D：把 1 当成包含、又漏掉 2 一侧。\n\n【口诀】分母不为零，根号内非负，条件取交集，端点看清楚。",
